// ===== Bika common lib =====
// SCOPE RULE: jsLib runs in its own ScriptBindings; only function definitions
// are shared via chainTo. source/java/baseUrl/result do NOT exist here, so
// every function takes (SRC, JV). java.* crypto is unusable -> Packages.*.

var PICA = {
  API_KEY: "C69BAF41DA5ABD1FFEDC6D2FEA56B",
  SECRET: "~d}$Q7$eIni=V)9\\RK/P.RM4;9[7|@/CA}b~OW!3?EV" + String.fromCharCode(96, 58, 60, 62) + "M7pddUBL5n|0/*Cn",
  BASE: "https://picaapi.picacomic.com/",
  DNS_POOL: ["172.67.194.19", "172.67.80.1", "104.21.235.3",
             "104.21.235.4", "104.21.91.145", "104.19.53.76",
             "104.21.80.1", "104.21.81.1", "104.16.0.1", "104.17.0.1"],
  INIT_URL: "http://68.183.234.72/init"
};

function picab_dnspool(SRC) {
  try {
    var cur = String(SRC.get("picab_dnspool") || "");
    if (cur && cur.indexOf(".") >= 0) { return cur; }
  } catch (e0) {}
  return PICA.DNS_POOL.join(",");
}

function picab_bytes(str) {
  return new Packages.java.lang.String(str).getBytes("UTF-8");
}

function picab_hmac(raw, key) {
  var m = Packages.javax.crypto.Mac.getInstance("HmacSHA256");
  m.init(new Packages.javax.crypto.spec.SecretKeySpec(picab_bytes(key), "HmacSHA256"));
  var b = m.doFinal(picab_bytes(raw));
  var s = "";
  for (var i = 0; i < b.length; i++) {
    var x = b[i] & 0xff;
    s += (x < 16 ? "0" : "") + x.toString(16);
  }
  return s;
}

function picab_nonce() {
  var s = "";
  for (var i = 0; i < 32; i++) {
    s += "0123456789abcdef".charAt(Math.floor(Math.random() * 16));
  }
  return s;
}

function picab_token(SRC) {
  try {
    var h = String(SRC.getLoginHeader() || "");
    if (h && h !== "null") {
      var m = h.match(new RegExp('"authorization"\\s*:\\s*"([^"]+)"'));
      if (m) { return m[1]; }
      return h;
    }
  } catch (e0) {}
  try { return String(SRC.get("picab_token") || ""); } catch (e1) { return ""; }
}

function picab_headers(path, method, SRC, JV) {
  var ts = String(Math.floor(Date.now() / 1000));
  var nonce = picab_nonce();
  var raw = (path + ts + nonce + method + PICA.API_KEY).toLowerCase();
  var sig = picab_hmac(raw, PICA.SECRET);
  var h = {
    "User-Agent": "okhttp/3.8.1",
    "accept": "application/vnd.picacomic.com.v1+json",
    "api-key": PICA.API_KEY,
    "app-channel": "2",
    "app-version": "2.2.1.2.3.3",
    "app-uuid": "defaultUuid",
    "app-platform": "android",
    "app-build-version": "44",
    "image-quality": "original",
    "time": ts,
    "nonce": nonce,
    "signature": sig
  };
  var tk = picab_token(SRC);
  if (tk && tk !== "null" && tk !== "") { h["authorization"] = tk; }
  return h;
}

function picab_opt(path, opt, SRC, JV) {
  opt = opt || {};
  opt.headers = picab_headers(path, opt.method || "GET", SRC, JV);
  if ((opt.method || "GET") === "POST") {
    opt.headers["Content-Type"] = "application/json; charset=UTF-8";
  }
  if (!opt.dnsIp) { opt.dnsIp = picab_dnspool(SRC); }
  if (!opt.retry) { opt.retry = 4; }
  if (!opt.timeout) { opt.timeout = 25000; }
  return PICA.BASE + path + "," + JSON.stringify(opt);
}

function picab_get(path, SRC, JV) {
  var last = "";
  for (var i = 0; i < 3; i++) {
    last = String(JV.ajax(picab_opt(path, { method: "GET" }, SRC, JV)) || "");
    if (last.charAt(0) === "{") { return last; }
    if (i < 2) {
      try { Packages.java.lang.Thread.sleep(1500); } catch (e0) {}
    }
  }
  return last;
}

function picab_post(path, bodyObj, SRC, JV) {
  var last = "";
  for (var i = 0; i < 3; i++) {
    last = String(JV.ajax(picab_opt(path, { method: "POST", body: JSON.stringify(bodyObj) }, SRC, JV)) || "");
    if (last.charAt(0) === "{") { return last; }
    if (i < 2) {
      try { Packages.java.lang.Thread.sleep(1500); } catch (e0) {}
    }
  }
  return last;
}

function picab_imgpath(media) {
  if (!media) { return ""; }
  var fs = String(media.fileServer || "").replace(new RegExp("/$"), "");
  var path = String(media.path || "").replace(new RegExp("^/?"), "");
  if (!path) { return ""; }
  if (!fs) { fs = "https://storage-b.picacomic.com"; }
  if (path.indexOf("tobs/") === 0) {
    return fs + "/static/" + path.substring(5);
  }
  if (path.indexOf("tobeimg/") === 0) {
    var idx = path.indexOf("/g:sm/");
    if (idx >= 0) {
      var b64 = path.substring(idx + 6);
      try {
        var real = String(new Packages.java.lang.String(
            Packages.android.util.Base64.decode(b64, 0), "UTF-8"));
        var i2 = real.indexOf("/static/");
        if (i2 >= 0) {
          var rest = real.substring(i2 + 8).replace(new RegExp("[^A-Za-z0-9_./-].*$"), "");
          return fs + "/static/" + rest;
        }
      } catch (e0) {}
    }
    return fs + "/static/" + path;
  }
  return fs + "/static/" + path;
}

function picab_cover(media, SRC, JV) {
  return picab_imgpath(media);
}

function picab_img(media) {
  if (!media) { return ""; }
  return picab_imgpath(media);
}

function picab_bookid(u) {
  var s = String(u || "");
  var c = s.indexOf(",{");
  if (c >= 0) { s = s.substring(0, c); }
  s = s.replace(new RegExp(".*comics/"), "");
  s = s.replace(new RegExp("[/?#].*$"), "");
  return s;
}

function picab_item(c, SRC, JV) {
  if (!c) { return null; }
  return {
    name: c.title || "",
    author: c.author || "",
    cover: picab_cover(c.thumb, SRC, JV),
    intro: "",
    kind: [(c.__group || ""),
           String(c.categories || []).replace(/,/g, " "),
           c.finished ? "完结" : "连载",
           c.likesCount ? c.likesCount + "♥" : ""].filter(Boolean).join(" · "),
    latest: "",
    word: "",
    url: PICA.BASE + "comics/" + (c._id || "")
        + ',{"method":"GET","retry":3,"timeout":20000,'
        + '"headers":' + JSON.stringify(picab_headers("comics/" + (c._id || ""), "GET", SRC))
        + ',"dnsIp":"' + picab_dnspool(SRC) + '"}'
  };
}

function picab_list(data) {
  var d = data || {};
  if (d.collections) {
    // collections: [{title, comics:[<comic>...]}] - comics is a plain array
    var flat = [];
    (d.collections || []).forEach(function (g) {
      (g.comics || []).forEach(function (c) {
        c.__group = g.title;
        flat.push(c);
      });
    });
    return flat;
  }
  var list = d.comics ? (d.comics.docs || d.comics) : (d.docs || d);
  if (!Array.isArray(list)) { list = []; }
  return list;
}

function PICAB_checkLogin(jv, SRC) {
  var msg = "";
  try {
    var txt = String(jv.ajax(picab_opt("users/profile", { method: "GET" }, SRC, jv)) || "");
    if (!txt) { msg = "检查失败: 无响应"; }
    else if (txt.charAt(0) !== "{") {
      msg = "❌ 检查失败: 网络超时（试试切换源站）";
      picab_say(jv, msg); return;
    }
    else {
      var jo = null;
      try { jo = JSON.parse(txt); } catch (e3) {}
      if (jo && jo.code === 200 && jo.data && jo.data.user) {
        var u = jo.data.user;
        msg = "✅ 已登录: " + (u.name || u.email || "未知")
              + " (Lv." + (u.level || "?") + ")"
              + (u.isPunched ? " [今日已签到]" : " [今日未签到]");
      } else if (jo && (jo.code === 401 || jo.code === 403)) {
        msg = "❌ 未登录，请填账号密码后点右上角✓登录";
      } else {
        msg = "⚠️ 状态未知: " + txt.substring(0, 60);
      }
    }
  } catch (e) { msg = "检查失败: " + e; }
  picab_say(jv, msg);
}

function PICAB_punch(jv, SRC) {
  var msg = "";
  try {
    var txt = String(jv.ajax(picab_opt("users/punch-in",
        { method: "POST", body: "{}" }, SRC, jv)) || "");
    if (!txt) { msg = "签到失败: 无响应"; }
    else if (txt.charAt(0) !== "{") {
      var why = txt.indexOf("SocketTimeout") >= 0 ? "网络超时" : "网络错误";
      msg = "❌ 签到失败: " + why + "（可试「🔄获取官方IP」或「☁️Cloudflare」换源站）";
      picab_say(jv, msg); return;
    }
    var jo = null;
    try { jo = JSON.parse(txt); } catch (e0) {}
    if (jo && jo.code === 200 && jo.data && jo.data.res) {
      var st = String(jo.data.res.status || "");
      if (st === "ok") { msg = "✅ 签到成功 (最近签到日 " + (jo.data.res.punchInLastDay || "?") + ")"; }
      else if (st === "fail") { msg = "📌 今日已签到，无需重复"; }
      else { msg = "签到状态: " + st; }
    } else if (jo && (jo.code === 401 || jo.code === 403)) {
      msg = "❌ 未登录，请先登录再签到";
    } else {
      msg = "❌ 签到失败: " + (jo && jo.message ? jo.message : txt.substring(0, 80));
    }
  } catch (e) { msg = "签到异常: " + e; }
  picab_say(jv, msg);
}

function PICAB_logout(jv, SRC) {
  try { SRC.putLoginHeader(""); } catch (e0) {}
  try { SRC.put("picab_token", ""); } catch (e5) {}
  picab_say(jv, "已退出登录（凭据已清除）");
}

function PICAB_updateDns(jv, SRC) {
  var msg = "";
  var r = "";
  try {
    r = String(jv.ajax(PICA.INIT_URL) || "");
  } catch (e) { r = ""; }
  if (!r) {
    msg = "❌ init 无响应（官方IP服务器不可达），当前源站未变更";
  } else if (r.charAt(0) !== "{") {
    var reason = r.indexOf("SocketTimeout") >= 0 ? "超时"
               : r.indexOf("UnknownHost") >= 0 ? "域名解析失败"
               : r.indexOf("ConnectException") >= 0 ? "连接被拒"
               : "网络错误";
    msg = "❌ init " + reason + "，当前源站未变更";
  } else {
    try {
      var jo = JSON.parse(r);
      var ips = (jo && jo.addresses) || [];
      if (ips.length) {
        var pool = ips.join(",");
        SRC.put("picab_dnspool", pool);
        try { SRC.refreshExplore(); } catch (e2) {}
        msg = "✅ 源站IP已更新: " + pool;
      } else {
        msg = "⚠️ init 未返回 IP，当前源站未变更";
      }
    } catch (e3) { msg = "❌ init 返回格式异常，当前源站未变更"; }
  }
  picab_say(jv, msg);
}

function PICAB_useStatic(jv, SRC) {
  try {
    SRC.put("picab_dnspool", PICA.DNS_POOL.join(","));
    SRC.refreshExplore();
    picab_say(jv, "✅ 已切换到 Cloudflare 静态源站，发现页签名已刷新");
  } catch (e) { picab_say(jv, "切换失败: " + e); }
}

function PICAB_refreshExplore(jv, SRC) {
  var msg = "";
  try {
    SRC.refreshExplore();
    msg = "✅ 发现页已刷新（重新生成签名，请回到发现页）";
  } catch (e) { msg = "刷新失败: " + e; }
  picab_say(jv, msg);
}

function PICAB_setSort(jv, SRC, idx) {
  try { SRC.put("picaSort", String(idx)); } catch (e0) {}
  var names = { "0": "最新发布", "1": "最早发布", "2": "最多爱心", "3": "最多观看" };
  picab_say(jv, "✅ 分类排序已切换: " + names[String(idx)]);
}

function PICAB_setTC(jv, SRC, on) {
  try { SRC.put("picaTC", on ? "1" : "0"); } catch (e0) {}
  picab_say(jv, on ? "✅ 分类/标签显示已切换: 简体" : "✅ 分类/标签显示已切换: 繁体");
}

function PICAB_diag(jv, SRC) {
  var lines = [];
  try {
    var t0 = Date.now();
    var r = String(jv.ajax(picab_opt("categories", { method: "GET" }, SRC, jv)));
    var ok1 = r.indexOf('"code"') >= 0 && r.indexOf('categories') >= 0 && r.indexOf('200') >= 0;
    lines.push("1.API签名+IP: " + (ok1 ? "✅" : "❌") + " " + (Date.now() - t0) + "ms" + (ok1 ? "" : " " + r.substring(0, 40).replace(/\n/g, " ")));
  } catch (e) { lines.push("1.API签名+IP: ❌ " + String(e).substring(0, 40)); }
  lines.push("2.当前IP池: " + picab_dnspool(SRC).substring(0, 40));
  try {
    var t1 = Date.now();
    var u1 = "https://storage-b.picacomic.com/static/sub_storage_1/ee/47/ee476c77-7b42-4485-8a92-ea99c9099ab2.jpg";
    var r1 = String(java.ajax(u1));
    lines.push("3.封面域(裸URL): " + (r1.length > 100000 ? "✅" : "❌") + " " + (Date.now() - t1) + "ms");
  } catch (e) { lines.push("3.封面域(裸URL): ❌ 超时"); }
  try {
    var t2 = Date.now();
    var u2 = "https://storage-b.picacomic.com/static/sub_storage_1/b4/b5/b4b5042d-4a5c-4cbb-8a2c-13060b05b990.jpg";
    var r2 = String(java.ajax(u2 + ',{"method":"GET","timeout":15000,"dnsIp":"' + picab_dnspool(SRC) + '"}'));
    lines.push("4.正文图(带IP): " + (r2.length > 100000 ? "✅" : "❌") + " " + (Date.now() - t2) + "ms");
  } catch (e) { lines.push("4.正文图(带IP): ❌ 超时"); }
  var msg = lines.join("\n");
  try { jv.upLoginData({ "登录状态": msg }); } catch (e1) {}
  try { jv.toast(msg); } catch (e2) {}
  try { jv.longToast(msg); } catch (e3) {}
}

function picab_say(jv, msg) {
  var stamped = "[" + new Date().toTimeString().substring(0, 8) + "] " + msg;
  try { jv.upLoginData({ "登录状态": stamped }); } catch (e1) {}
  msg = stamped;
  try { jv.toast(msg); } catch (e2) {}
  try { jv.longToast(msg); } catch (e3) {}
  try { jv.reLoginView(false); } catch (e4) {}
}

